'use strict';
const c28={orderPage:1,productQuery:'',inventoryMode:'',productPage:1,orderFrom:'',orderTo:'',draft:null,year:2026};
function c28Value(id){return document.getElementById(id)?.value??'';}
function c28Cash(id){const value=c28Value(id);return value===''?null:Math.round(Number(value)*100);}
function c28Date(value){return ERP.engines.operations.dateOnly(value)||'—';}
function c28Rows(o){return ERP.engines.inventory.orderItems(o);}
function c28Commercial(o){return o.commercialStatus==='Cancelada'||o.status==='cancelled'?'Cancelada':'Activa';}
function c28Payment(o){return ({unknown:'No informado',paid:'Pagado',refunded:'Reembolsado',partially_refunded:'Reembolso parcial'})[o.paymentStatus]||o.paymentStatus||'No informado';}
function c28Operational(o){if(o.stockMode==='historical')return {text:'Histórico · sin movimiento',tone:'slate'};if(o.returnStatus==='inspection')return {text:'En inspección',tone:'amber'};if(o.returnStatus==='requested')return {text:'Devolución en camino',tone:'amber'};if(o.returnStatus==='restocked')return {text:'Reintegrado',tone:'green'};if(o.returnStatus==='rejected')return {text:'No vendible',tone:'red'};return ({reserved:{text:'Reservado',tone:'amber'},shipped:{text:'Enviado',tone:'blue'},delivered:{text:'Entregado',tone:'green'},cancelled:{text:'Cancelado',tone:'slate'}})[o.status]||{text:o.status,tone:'slate'};}
orderBadge=function(o){const b=c28Operational(o);return badge(b.text,b.tone);};
issues=function(){const list=[];for(const o of state.orders){const r=o.reconciliation;if(r?.estimate&&r.depositCents!=null&&Math.abs(r.depositCents-r.estimate.netCents)>1)list.push({type:'settlement',order:o,title:'Diferencia de liquidación',detail:o.number+' · '+money(r.depositCents-r.estimate.netCents),tone:'amber'});if(o.incident||['Pendiente','En seguimiento'].includes(o.followupStatus)||['requested','inspection'].includes(o.returnStatus))list.push({type:'order',order:o,title:o.returnStatus==='inspection'?'Devolución en inspección':o.returnStatus==='requested'?'Devolución en camino':'Seguimiento pendiente',detail:o.number+' · '+o.market,tone:'amber'});}for(const p of state.products){if(p.stockStatus==='Por revisar'||p.review)list.push({type:'stock',product:p,title:'Ficha por revisar',detail:p.name,tone:'amber'});else if(D.available(p)<=p.minStock)list.push({type:'stock',product:p,title:'Existencia baja',detail:p.name+' · '+D.available(p)+' disponibles',tone:'amber'});}return list;};
totals=function(){const active=state.orders.filter(o=>c28Commercial(o)==='Activa');const settled=state.orders.filter(o=>o.reconciliation?.estimate&&o.reconciliation.depositCents!=null);return {sales:active.reduce((s,o)=>s+D.orderTotal(o),0),reserved:state.products.reduce((s,p)=>s+(p.reserved||0),0),pending:state.orders.filter(o=>o.status==='reserved').length,available:state.products.reduce((s,p)=>s+D.available(p),0),settlementExpected:settled.reduce((s,o)=>s+o.reconciliation.estimate.netCents,0),settlementPaid:settled.reduce((s,o)=>s+o.reconciliation.depositCents,0),settled};};
function c28Dashboard(){
 const selected=state.orders.filter(o=>c28Date(o.creationDate||o.date).slice(0,4)===String(c28.year)),active=selected.filter(o=>c28Commercial(o)==='Activa'),sales=active.reduce((s,o)=>s+D.orderTotal(o),0),allIssues=issues(),recon=ERP.engines.reconciliation.summary(selected),calendar=ERP.engines.operations.buildCalendar(state,ERP.today());
 const channels=[...new Set([...markets,...selected.map(o=>o.market)])],per=channels.map(m=>({market:m,sales:active.filter(o=>o.market===m).reduce((s,o)=>s+D.orderTotal(o),0),orders:active.filter(o=>o.market===m).length})),max=Math.max(1,...per.map(a=>a[chartMode]));
 const pending=state.orders.filter(o=>['Pendiente','En seguimiento'].includes(o.followupStatus)).length,returns=state.orders.filter(o=>['requested','inspection'].includes(o.returnStatus)).length;
 const payments=Array.isArray(calendar)?calendar:(calendar.rows||[]),dated=payments.filter(r=>r.dueDate),unconfigured=payments.filter(r=>!r.dueDate&&r.balanceCents>0);
 return `${pageHead('PANORAMA DE OPERACIÓN','Tu operación, a la vista.','Pedidos, inventario y pagos. Todo lo que necesitas para seguir tu día.',`<button class="btn" data-v28="backup">${icon('download')} Respaldo</button>${primaryNew()}`)}
 <div class="intro-strip">${icon('info')}<span>${datasetNote()} Las integraciones con marketplaces aún no están conectadas.</span><button class="text" data-v28="guide">Ver recorrido ↗</button></div>
 ${PaymentAlerts28.panel()}
 <div class="dashboard-period"><span>Resultados por fecha de creación SICAR / registro</span><label>Año <select id="c28-year">${[2025,2026,2027].map(y=>`<option ${y===c28.year?'selected':''}>${y}</option>`).join('')}</select></label><button class="btn small" data-view="statistics">Explorar periodos</button></div>
 <div class="metrics">${metric('Venta bruta activa',whole(sales),active.length+' ventas activas · '+c28.year,'arrowup','MXN')}${metric('Pedidos por preparar',state.orders.filter(o=>o.status==='reserved').length,totals().reserved+' unidades reservadas','bag')}${metric('Disponible para vender',totals().available,'Después de reservas y stock de seguridad','box','uds.')}${metric('Diferencia conciliada',recon.matchedDifferenceCents==null?'—':whole(recon.matchedDifferenceCents),(recon.matchedCount||0)+' ventas con estimación y depósito','wallet','MXN')}</div>
 <div class="quick-queues"><button data-v28-filter="pending"><strong>${pending}</strong><span>Seguimientos pendientes</span>${icon('arrow')}</button><button data-v28-filter="returns"><strong>${returns}</strong><span>Devoluciones en proceso</span>${icon('arrow')}</button><button data-v28-filter="no-stock"><strong>${state.products.filter(p=>D.available(p)===0).length}</strong><span>Productos sin disponible</span>${icon('arrow')}</button><button data-view="calendar"><strong>${unconfigured.length}</strong><span>Cuotas sin fecha configurada</span>${icon('arrow')}</button></div>
 ${MarketUI.overview(state.orders)}
 <div class="dashboard-mid"><section class="panel"><div class="panel-head"><div><h2>Actividad por marketplace</h2><div class="panel-sub">Ventas activas del año seleccionado</div></div><div class="chart-tabs"><button class="${chartMode==='sales'?'active':''}" data-chart="sales">Importe</button><button class="${chartMode==='orders'?'active':''}" data-chart="orders">Pedidos</button></div></div><div class="panel-body"><div class="bars">${per.map(a=>`<div class="bar-row"><div class="bar-name">${MarketUI.logo(a.market)}<span>${esc(a.market)}</span></div><div class="bar-track"><div class="bar-fill" style="width:${a[chartMode]/max*100}%;background:${MarketUI.get(a.market).color}"></div></div><div class="bar-number">${chartMode==='sales'?whole(a.sales):a.orders+' pedidos'}</div></div>`).join('')}</div><div class="chart-foot"><span>${active.length} ventas activas</span><span>${selected.length-active.length} canceladas · ${c28.year}</span></div></div></section><section class="panel"><div class="panel-head"><div><h2>Necesitan tu atención</h2><div class="panel-sub">Pagos, seguimiento, mercancía y diferencias</div></div>${badge(allIssues.length,'amber')}</div><div class="attention-list">${allIssues.slice(0,5).map(i=>`<button class="attention-item" ${PaymentAlerts28.issueTarget(i)}><span class="attention-icon">${icon(i.type==='stock'?'box':'alert')}</span><span class="attention-text"><strong>${esc(i.title)}</strong><small>${esc(i.detail)}</small></span>${icon('arrow')}</button>`).join('')||'<div class="empty">No hay asuntos pendientes.</div>'}</div><div class="connected-footer"><button class="btn text" data-view="incidents">Abrir todos los pendientes ↗</button></div></section></div>
 <section class="panel"><div class="panel-head"><div><h2>Pedidos recientes</h2><div class="panel-sub">Con el número original y sus referencias de operación</div></div><button class="btn text" data-view="orders">Ver todos ${icon('arrow')}</button></div>${orderTable([...state.orders].sort((a,b)=>String(b.creationDate||b.date).localeCompare(String(a.creationDate||a.date))).slice(0,6))}</section>
 <div class="module-cards spacer-top">${[['purchases','Compras y mercancía',state.purchases?.length||0,'Documentos, partidas, recepción y abonos','truck'],['expenses','Gastos y abonos',state.expenses?.length||0,'Clasificación, saldos y parcialidades','wallet'],['settlements','Conciliación por lotes',state.orders.filter(o=>o.reconciliation?.selected).length,'Ventas seleccionadas para trabajar en conjunto','calculator']].map(([v,title,n,sub,ic])=>`<button class="panel module-card" data-view="${v}">${icon(ic)}<div><strong>${title}</strong><p>${sub}</p></div><b>${n}</b>${icon('arrow')}</button>`).join('')}</div>`;
}
orderRows=function(orders){return orders.map(o=>{const lines=c28Rows(o),p=product(o.sku);return `<tr><td><button class="row-title" data-order="${esc(o.id)}">${esc(o.number||'Pedido por identificar')}</button><span class="subtext">${esc(o.id)}${o.sicar?' · SICAR '+esc(o.sicar):''}</span></td><td>${marketTag(o.market)}<span class="subtext">${c28Date(o.documentDate||o.date)}</span></td><td><span>${esc(lines[0]?.name||p?.name||o.productNames||'Sin partidas verificadas')}</span><span class="subtext">${lines.length>1?lines.length+' partidas · ':''}${lines.reduce((s,l)=>s+l.qty,0)} unidades ${lines.length?'':'· revisar origen'}</span></td><td>${badge(c28Commercial(o),c28Commercial(o)==='Activa'?'green':'slate')}<span class="subtext">${orderBadge(o)}</span></td><td class="table-price">${money(D.orderTotal(o))}</td><td><button class="more-arrow" data-order="${esc(o.id)}" aria-label="Abrir pedido ${esc(o.number||o.id)}">${icon('arrow')}</button></td></tr>`;}).join('');};
filteredOrders=function(){const q=orderQuery.toLowerCase();return state.orders.filter(o=>(!marketFilter||o.market===marketFilter)&&(!c28.orderFrom||(o.documentDate||o.date||'').slice(0,10)>=c28.orderFrom)&&(!c28.orderTo||(o.documentDate||o.date||'').slice(0,10)<=c28.orderTo)&&(!statusFilter||(statusFilter==='pending'?['Pendiente','En seguimiento'].includes(o.followupStatus):statusFilter==='returns'?['requested','inspection'].includes(o.returnStatus):statusFilter==='issues'?(o.incident||o.review):statusFilter==='cancelled'?c28Commercial(o)==='Cancelada':o.status===statusFilter))&&(!q||[o.number,o.literalNumber,o.id,o.ventiId,o.sicar,o.sicarUuid,o.market,o.sku,o.productNames,...c28Rows(o).map(l=>l.name+' '+l.sku+' '+l.upc)].join(' ').toLowerCase().includes(q)));};
function c28OrdersPage(){const list=filteredOrders(),pages=Math.max(1,Math.ceil(list.length/50));c28.orderPage=Math.min(c28.orderPage,pages);return `${pageHead('OPERACIÓN / PEDIDOS','Cada venta, una historia completa.','Pedido original, partidas, seguimiento y movimientos en una sola ficha.',`<button class="btn" data-v28="orders-export">${icon('download')} Exportar</button>${primaryNew()}`)}${pageTabs([['','Todos'],['reserved','Por preparar'],['pending','Seguimiento'],['returns','Devoluciones'],['cancelled','Canceladas'],['historical','Histórico V28']],statusFilter,'data-status')}${MarketUI.chips(marketFilter,state.orders.reduce((counts,o)=>(counts[o.market]=(counts[o.market]||0)+1,counts),{}))}<div class="filterbar"><label class="field-search">${icon('search')}<input id="order-search" value="${esc(orderQuery)}" aria-label="Filtrar pedidos" placeholder="Pedido, folio SICAR, SKU, UPC o producto…"></label><select id="market-filter" aria-label="Filtrar marketplace"><option value="">Todos los marketplaces</option>${[...new Set([...markets,...state.orders.map(o=>o.market)])].map(m=>`<option ${m===marketFilter?'selected':''}>${esc(m)}</option>`).join('')}</select><button class="btn" data-action="clear-filters">Limpiar</button></div><div class="filterbar c28-small-filters">${ERP.field('c28-order-from','Desde',c28.orderFrom,'date')}${ERP.field('c28-order-to','Hasta',c28.orderTo,'date')}<span class="tiny">Filtro de fecha documental · ${list.length} resultados</span></div><section class="panel">${orderTable(list.slice((c28.orderPage-1)*50,c28.orderPage*50))}<div class="table-footer"><span>${list.length} ventas · ${datasetNote()}</span><div class="pager"><button class="btn small" data-c28-page="${c28.orderPage-1}" ${c28.orderPage<=1?'disabled':''}>Anterior</button><span>${c28.orderPage} / ${pages}</span><button class="btn small" data-c28-page="${c28.orderPage+1}" ${c28.orderPage>=pages?'disabled':''}>Siguiente</button></div></div></section>`;}
orderDetails=function(id){const o=state.orders.find(o=>o.id===id);if(!o)return;drawerOrder=id;const lines=c28Rows(o),r=o.reconciliation||{},commands=[];
 if(o.stockMode!=='historical'&&o.status==='reserved')commands.push(['ship','Registrar envío','primary']);
 if(o.status==='shipped')commands.push(['deliver','Registrar entrega','primary']);
 if(c28Commercial(o)==='Activa')commands.push(['cancel','Cancelar venta','']);
 if(o.paymentStatus!=='refunded')commands.push(['refund','Registrar reembolso','']);
 if(!['requested','inspection','restocked','rejected'].includes(o.returnStatus)&&o.status!=='reserved')commands.push(['return_request','Solicitar devolución','']);
 if(o.returnStatus==='requested')commands.push(['return_receive','Recibir físicamente','primary']);
 if(o.returnStatus==='inspection')commands.push(['return_restock','Aprobar reintegro','primary'],['return_reject','Marcar no vendible','']);
 showDrawer(`<div class="drawer-header"><div><div class="eyebrow">PEDIDO ${esc(o.id)}</div><h2 id="drawer-title">${esc(o.number||'Pedido por identificar')}</h2>${marketTag(o.market)} ${badge(c28Commercial(o),c28Commercial(o)==='Activa'?'green':'slate')}</div><button class="icon-button" data-action="close-drawer" aria-label="Cerrar pedido">${icon('close')}</button></div>
 <div class="detail-grid">${detailItem('FOLIO SICAR',o.sicar||'Sin informar')}${detailItem('FECHA DOCUMENTAL',c28Date(o.documentDate||o.date))}${detailItem('CREACIÓN SICAR / REGISTRO',c28Date(o.creationDate))}${detailItem('PAGO',c28Payment(o))}${detailItem('SEGUIMIENTO',o.followupStatus||'Sin pendiente')}${detailItem('PRIORIDAD',o.priority||'Normal')}</div><div class="spacer-top">${orderBadge(o)} ${o.stockMode==='historical'?badge('No modifica stock al importar','slate'):badge('Inventario administrado','blue')}</div>
 <div class="drawer-block"><h3>Partidas de la venta</h3><div class="table-wrap"><table><thead><tr><th>Producto</th><th>Unidades</th><th>Importe</th></tr></thead><tbody>${lines.map(l=>`<tr><td><button class="row-title" data-product="${esc(l.sku)}">${esc(l.name||l.sku)}</button><span class="subtext">${esc(l.sku)} · ${esc(l.upc||'')}</span></td><td>${l.qty}</td><td>${money(l.totalCents)}</td></tr>`).join('')||'<tr><td colspan="3">Sin partidas verificadas. La estimación requiere completar el origen.</td></tr>'}</tbody></table></div><div class="calc-line"><span>Envío cobrado al comprador</span><strong>${money(o.shippingChargedCents||0)}</strong></div><div class="calc-line total"><span>Total de venta</span><strong>${money(D.orderTotal(o))}</strong></div></div>
 <div class="drawer-block"><h3>Operación y seguimiento</h3><div class="detail-actions">${commands.map(([action,label,tone])=>`<button class="btn ${tone}" data-c28-order-action="${action}" data-id="${esc(o.id)}">${label}</button>`).join('')}<button class="btn" data-c28-order-action="note" data-id="${esc(o.id)}">Editar seguimiento</button><button class="btn" data-c28-order-action="resolve" data-id="${esc(o.id)}">Resolver seguimiento</button></div>${o.incident?'<div class="info-box spacer-top">'+esc(o.incident)+'</div>':''}<p class="record-notes">${esc(o.comments||'Sin notas.')}</p></div>
 <div class="drawer-block"><div class="panel-head" style="padding:0 0 14px"><h3>Conciliación</h3><button class="btn small" data-c28-recon="${esc(o.id)}">Abrir conciliación</button></div><div class="calc-line"><span>Estado</span><strong>${esc(r.status||'Sin revisar')}</strong></div><div class="calc-line"><span>Depósito esperado</span><strong>${nullMoney(r.estimate?.netCents)}</strong></div><div class="calc-line"><span>Depósito confirmado</span><strong>${nullMoney(r.depositCents)}</strong></div><div class="calc-line"><span>Borrador por guardar</span><strong>${nullMoney(r.draft?.amountCents)}</strong></div><p class="tiny">El estado de conciliación conserva por separado el reembolso y la devolución física.</p></div>
 <div class="drawer-block"><h3>Origen y referencias</h3><p class="small-note">${esc(o.sourceDescription||o.source||'AIMERKA')} · ${esc(o.partsStatus||'')}<br>${esc(o.sourceSheet||'')} ${o.sourceRow?'· fila '+o.sourceRow:''}</p>${/^https:\/\/app\.sicarx\.com\//.test(o.sicarUrl||'')?`<a class="btn small" href="${esc(o.sicarUrl)}" target="_blank" rel="noopener">Abrir referencia SICAR ↗</a>`:''}${o.review?'<div class="info-box">'+esc(o.review)+'</div>':''}</div><div class="drawer-block"><h3>Historial</h3><ul class="timeline">${(o.history||[]).map(h=>`<li>${esc(h.label)}<small>${c28Date(h.date)} · ${esc(h.actor||'')}</small></li>`).join('')||'<li>Registro importado de V28; sin movimientos nuevos.</li>'}</ul></div>`);
};
function c28ActionForm(action,id){const o=state.orders.find(o=>o.id===id);if(!o)return;const labels={ship:'Registrar envío',deliver:'Registrar entrega',cancel:'Cancelar venta',refund:'Registrar reembolso',return_request:'Solicitar devolución',return_receive:'Recibir devolución física',return_restock:'Aprobar reintegro',return_reject:'Clasificar como no vendible',note:'Editar seguimiento',resolve:'Resolver seguimiento'};const financial=action==='refund',note=action==='note',reasonRequired=['cancel','refund','return_reject','resolve'].includes(action);
 showModal(`<h2 id="modal-title">${labels[action]}</h2><p class="modal-subtitle">${esc(o.number||o.id)} · ${esc(o.market)}</p><form id="c28-order-action-form" data-type="${action}" data-id="${esc(id)}">${note?`<div class="form-grid">${ERP.select('c28-followup','Seguimiento',['Sin pendiente','Pendiente','En seguimiento','Resuelto'],o.followupStatus)}${ERP.select('c28-priority','Prioridad',['Normal','Importante'],o.priority)}</div>`:''}${financial?ERP.field('c28-refund-amount','Importe total del reembolso registrado (MXN)',D.orderTotal(o)/100,'number','min="0.01" step="0.01" required'):''}<div class="field spacer-top"><label for="c28-reason">${note?'Notas de seguimiento':'Motivo / referencia'}${reasonRequired?' *':''}</label><textarea id="c28-reason" rows="4" ${reasonRequired?'required':''}>${note?esc(o.comments||''):''}</textarea></div>${action==='return_receive'&&o.stockMode==='historical'?'<label class="check-line spacer-top"><input type="checkbox" id="c28-confirm-physical" required> Confirmo una recepción física actual. Se agregará mercancía a inspección.</label>':''}<div class="info-box blue spacer-top">${action==='ship'?'Se cerrarán las reservas y se registrará la salida física una sola vez.':action==='refund'?'El registro financiero no reincorpora existencias.':action==='return_receive'?'Las unidades pendientes de la venta entrarán a inspección.':action==='return_restock'?'Solo se reincorporarán las unidades recibidas y pendientes de inspección.':action==='cancel'?'Antes del envío se libera la reserva. Después del envío queda un seguimiento de devolución.':'El cambio quedará en el historial de la operación.'}</div><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Cancelar</button><button class="btn primary" type="submit">Guardar</button></div></form>`);
}
window.saleFormV28=function(){c28.draft={market:'Sears',number:'',sicar:'',documentDate:ERP.today(),account:'HAVANI Technologies México',shippingChargedCents:0,comments:'',priority:'Normal',followupStatus:'Sin pendiente',items:[{sku:state.products.find(p=>D.available(p)>0)?.sku||state.products[0]?.sku,qty:1,unitPriceCents:null}]};c28SaleForm();};
function c28ReadSale(){const d=c28.draft;for(const f of ['market','number','sicar','documentDate','account','comments','priority','followupStatus','warehouseId'])d[f]=c28Value('c28-sale-'+f);d.shippingChargedCents=c28Cash('c28-sale-shipping')||0;d.items=[...document.querySelectorAll('[data-c28-sale-row]')].map(row=>({sku:row.querySelector('[data-field="sku"]').value,qty:Number(row.querySelector('[data-field="qty"]').value),unitPriceCents:Math.round(Number(row.querySelector('[data-field="price"]').value)*100)}));return d;}
function c28SaleForm(){const d=c28.draft;showModal(`<h2 id="modal-title">Registrar venta</h2><p class="modal-subtitle">Conserva el pedido original y registra todas sus partidas.</p><form id="c28-sale-form"><div class="form-grid">${ERP.warehouseField('c28-sale-warehouseId',d.warehouseId||'principal')}${ERP.select('c28-sale-market','Marketplace',markets,d.market)}${ERP.field('c28-sale-number','Pedido original *',d.number,'text','required maxlength="120"')}${ERP.field('c28-sale-sicar','Folio SICAR (si existe)',d.sicar)}${ERP.field('c28-sale-documentDate','Fecha de venta *',d.documentDate,'date','required max="'+ERP.today()+'"')}${ERP.field('c28-sale-account','Cuenta vendedora',d.account)}${ERP.field('c28-sale-shipping','Envío cobrado al comprador (MXN)',d.shippingChargedCents/100,'number','min="0" step="0.01"')}</div><div class="form-section-head"><h3>Partidas</h3><button class="btn small" type="button" data-v28="sale-add-line">${icon('plus')} Agregar producto</button></div><div class="c28-sale-lines">${d.items.map((l,i)=>{const p=product(l.sku);return `<div class="c28-sale-line" data-c28-sale-row="${i}"><div class="field"><label>Producto / SKU / UPC</label><select data-field="sku" data-c28-sale-product="${i}">${state.products.filter(p=>p.status!=='INACTIVO').map(p=>`<option value="${esc(p.sku)}" ${l.sku===p.sku?'selected':''}>${esc(p.name)} · ${esc(p.sku)} · ${ERP.warehouseAvailable(p,d.warehouseId||'principal')} disp. en almacén</option>`).join('')}</select></div><div class="field"><label>Unidades</label><input data-field="qty" type="number" min="1" step="1" value="${l.qty}" required></div><div class="field"><label>Precio unitario MXN</label><input data-field="price" type="number" min="0" step="0.01" value="${(l.unitPriceCents??p?.priceCents??0)/100}" required></div><button class="icon-button" type="button" data-c28-remove-line="${i}" aria-label="Quitar partida ${i+1}" ${d.items.length===1?'disabled':''}>${icon('close')}</button></div>`;}).join('')}</div><div class="form-grid spacer-top">${ERP.select('c28-sale-priority','Prioridad',['Normal','Importante'],d.priority)}${ERP.select('c28-sale-followupStatus','Seguimiento',['Sin pendiente','Pendiente'],d.followupStatus)}</div><div class="field spacer-top"><label for="c28-sale-comments">Observaciones</label><textarea id="c28-sale-comments" rows="3">${esc(d.comments)}</textarea></div><div class="info-box blue spacer-top">El pedido reservará existencias disponibles. El envío posterior registrará la salida física.</div><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Cancelar</button><button class="btn primary" type="submit">Guardar venta y reservar</button></div></form>`);}
function c28Inventory(){const q=inventoryQuery.toLowerCase(),list=state.products.filter(p=>[p.name,p.sku,p.upc,p.brand,...(p.skuAliases||[])].join(' ').toLowerCase().includes(q)&&(!c28.inventoryMode||(c28.inventoryMode==='empty'?D.available(p)===0:c28.inventoryMode==='low'?D.available(p)<=p.minStock:p.stockStatus==='Por revisar'||p.sourceStock==null||p.sourceStock<0)));return `${pageHead('OPERACIÓN / INVENTARIO','Un inventario que puedes explicar.','La lógica de reservas, inspección y reintegros se conserva y se amplía con el catálogo de V28.',`<button class="btn" data-v28="inventory-export">${icon('download')} Exportar</button>${primaryNew()}`)}<div class="mini-metrics">${metric('Físico vendible',state.products.reduce((s,p)=>s+(p.good||0),0),'Incluye unidades reservadas','box','uds.')}${metric('Reservas activas',state.products.reduce((s,p)=>s+(p.reserved||0),0),'Pedidos pendientes de envío','bag','uds.')}${metric('En inspección',state.products.reduce((s,p)=>s+(p.quarantine||0),0),'Mercancía recibida por revisar','shield','uds.')}</div><div class="filterbar"><label class="field-search">${icon('search')}<input id="inventory-search" value="${esc(inventoryQuery)}" placeholder="Producto, SKU, UPC o marca…" aria-label="Buscar producto en inventario"></label><select id="c28-inventory-mode"><option value="">Todo el catálogo</option>${[['empty','Sin disponible'],['low','Bajo el mínimo'],['review','Origen por revisar']].map(([v,l])=>`<option value="${v}" ${c28.inventoryMode===v?'selected':''}>${l}</option>`).join('')}</select></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Producto / SKU</th><th>Físico</th><th>Reserva</th><th>Inspección</th><th>No vendible</th><th>Seguridad</th><th>Disponible</th><th></th></tr></thead><tbody>${list.map(p=>`<tr><td><button class="row-title" data-product="${esc(p.sku)}">${esc(p.name)}</button><span class="subtext">${esc(p.sku)} · UPC ${esc(p.upc)}</span>${p.stockStatus==='Por revisar'||p.sourceStock==null||p.sourceStock<0?badge('Origen por revisar','amber'):''}</td><td>${p.good}</td><td>${p.reserved}</td><td>${p.quarantine}</td><td>${p.damaged}</td><td>${p.safety}</td><td><strong class="${D.available(p)<=p.minStock?'warn':''}">${D.available(p)}</strong></td><td><button class="btn small" data-c28-adjust="${esc(p.sku)}">Ajustar</button></td></tr>`).join('')||'<tr><td colspan="8" class="empty">No hay coincidencias.</td></tr>'}</tbody></table></div><div class="table-footer">${list.length} productos · Disponible = físico vendible − reserva − seguridad</div></section><section class="panel spacer-top"><div class="panel-head"><h2>Movimientos de inventario</h2><span class="tiny">Las ventas históricas no vuelven a descontarse</span></div><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Producto</th><th>Tipo de existencia</th><th>Movimiento</th><th>Antes → después</th><th>Referencia</th></tr></thead><tbody>${(state.movements||[]).slice(0,100).map(m=>`<tr><td>${c28Date(m.date)}</td><td>${esc(m.sku)}</td><td>${esc({good:'Vendible',reserved:'Reservado',quarantine:'Inspección',damaged:'No vendible',safety:'Seguridad'}[m.pool]||m.pool)}</td><td>${m.delta>0?'+':''}${m.delta}</td><td>${m.before} → ${m.after}</td><td>${esc(m.reference)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Todavía no hay movimientos registrados en este espacio.</td></tr>'}</tbody></table></div></section>`;}
function c28Products(){const q=c28.productQuery.toLowerCase(),list=state.products.filter(p=>[p.name,p.sku,p.upc,p.brand,p.category,...(p.skuAliases||[])].join(' ').toLowerCase().includes(q));return `${pageHead('CATÁLOGO / PRODUCTOS','Un producto. Todos sus canales.','Catálogo, categorías, costos y excepciones comerciales de V28.',`<button class="btn" data-v28="products-export">${icon('download')} Exportar</button><button class="btn primary" data-v28="product-new">${icon('plus')} Registrar producto</button>`)}<div class="filterbar"><label class="field-search">${icon('search')}<input id="c28-product-query" value="${esc(c28.productQuery)}" placeholder="Producto, marca, SKU, UPC o categoría…" aria-label="Buscar en catálogo"></label><span class="tiny">${list.length} productos</span><button class="btn" data-view="configuration">Categorías y mapeos</button></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Producto</th><th>Marca / categoría</th><th>Costo</th><th>Precio de mercado</th><th>Envío</th><th>Disponible</th><th></th></tr></thead><tbody>${list.map(p=>`<tr><td><button class="row-title" data-product="${esc(p.sku)}">${esc(p.name)}</button><span class="subtext">${esc(p.sku)} · ${esc(p.upc)}</span></td><td>${esc(p.brand)}<span class="subtext">${esc(p.category)}</span></td><td>${money(p.costCents)}</td><td>${money(p.priceCents)}</td><td>${esc(p.shippingType||'Por configurar')}</td><td>${D.available(p)}</td><td><button class="btn small" data-c28-product-edit="${esc(p.sku)}">Actualizar</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No hay productos que coincidan.</td></tr>'}</tbody></table></div></section>`;}
productDetails=function(sku){const p=product(sku);if(!p)return;drawerOrder=null;const related=state.orders.filter(o=>c28Rows(o).some(l=>l.sku===sku));showDrawer(`<div class="drawer-header"><div><div class="eyebrow">FICHA CENTRAL DE PRODUCTO</div><h2 id="drawer-title">${esc(p.name)}</h2><span class="subtext">${esc(p.sku)} · ${esc(p.upc)}</span></div><button class="icon-button" data-action="close-drawer" aria-label="Cerrar ficha">${icon('close')}</button></div><div class="detail-grid">${detailItem('MARCA',p.brand)}${detailItem('CATEGORÍA INTERNA',p.category)}${detailItem('COSTO',money(p.costCents))}${detailItem('PRECIO DE MERCADO',money(p.priceCents))}${detailItem('CLAVE SAT',p.satCode||'Sin informar')}${detailItem('ENVÍO',p.shippingType||'Sin configurar')}${detailItem('EXISTENCIA EN ORIGEN',p.sourceStock==null?'Sin informar':p.sourceStock)}${detailItem('ESTADO',p.status||'OK')}</div><div class="stock-summary spacer-top"><div>Físico vendible<strong>${p.good}</strong></div><div>Reservado<strong>${p.reserved}</strong></div><div>Disponible<strong>${D.available(p)}</strong></div></div><div class="detail-actions spacer-top"><button class="btn primary" data-c28-product-edit="${esc(sku)}">Actualizar producto</button><button class="btn" data-c28-adjust="${esc(sku)}">Ajustar inventario</button><button class="btn" data-c28-recommend="${esc(sku)}">Recomendar precio</button></div>${p.review?'<div class="info-box spacer-top">'+esc(p.review)+'</div>':''}<div class="drawer-block"><h3>Categorías por marketplace</h3>${ERP.engines.pricing.CHANNELS.map(channel=>{const category=ERP.engines.pricing.resolveCategory(state.config,p,channel);return `<div class="calc-line"><span>${esc(channel)}</span><strong>${esc(typeof category==='object'?(category.category||category.value||'Por configurar'):category||'Por configurar')}</strong></div>`;}).join('')}</div><div class="drawer-block"><h3>Pedidos relacionados · ${related.length}</h3>${related.slice(0,30).map(o=>`<button class="attention-item" data-order="${esc(o.id)}"><span class="attention-text"><strong>${esc(o.number||o.id)}</strong><small>${esc(o.market)} · ${money(D.orderTotal(o))}</small></span>${orderBadge(o)}</button>`).join('')||'<p class="small-note">Sin pedidos relacionados.</p>'}</div>`);};
function c28ProductForm(sku){const p=sku?product(sku):{sku:'',upc:'',name:'',brand:'',category:'',costCents:0,priceCents:0,shippingType:'Pequeño',shippingException:'Automático',safety:0,minStock:3,categories:{},categoryOverrides:{},status:'OK'},cat=(state.config.categoryMappings||[]).map(r=>r.category);showModal(`<h2 id="modal-title">${sku?'Actualizar producto':'Registrar producto'}</h2><p class="modal-subtitle">Una ficha central con excepciones por canal.</p><form id="c28-product-form" data-original="${esc(sku||'')}"><div class="form-grid">${ERP.field('c28-product-sku','SKU vendedor *',p.sku,'text','required '+(sku?'readonly':''))}${ERP.field('c28-product-upc','UPC / EAN *',p.upc,'text','required '+(sku?'readonly':''))}<div class="field wide"><label for="c28-product-name">Nombre *</label><input id="c28-product-name" value="${esc(p.name)}" required maxlength="250"></div>${ERP.field('c28-product-brand','Marca *',p.brand,'text','required list="c28-brand-list"')}${ERP.select('c28-product-category','Categoría de inventario',cat,p.category)}${ERP.field('c28-product-cost','Costo promedio (MXN)',p.averageCostMxn??p.costCents/100,'number','min="0" step="0.000001" required')}${ERP.field('c28-product-price','Precio de mercado (MXN)',p.priceCents/100,'number','min="0" step="0.01" required')}${ERP.select('c28-product-shipping','Tipo de envío',['Pequeño','Mediano','Grande'],p.shippingType)}${ERP.select('c28-product-shipping-exception','Regla de envío',['Automático','Pequeño','Mediano','Grande'],p.shippingException||'Automático')}${ERP.field('c28-product-sat','Clave SAT',p.satCode)}${ERP.field('c28-product-department','Departamento',p.department)}${ERP.field('c28-product-safety','Stock de seguridad',p.safety,'number','min="0" step="1"')}${ERP.field('c28-product-min','Mínimo de alerta',p.minStock,'number','min="0" step="1"')}${ERP.select('c28-product-status','Estado',['OK','INACTIVO'],p.status||'OK')}</div><datalist id="c28-brand-list">${[...new Set(state.products.map(p=>p.brand))].map(v=>'<option value="'+esc(v)+'">').join('')}</datalist><div class="form-section-head"><h3>Excepciones de categoría por marketplace</h3></div><div class="form-grid">${ERP.engines.pricing.CHANNELS.map((channel,i)=>ERP.select('c28-product-override-'+i,channel,ERP.engines.pricing.listCategories(state.config,channel,{mapping:true}),p.categoryOverrides?.[channel]||'','Automático · usar mapeo')).join('')}</div><div class="field spacer-top"><label for="c28-product-review">Observaciones / revisión</label><textarea id="c28-product-review" rows="3">${esc(p.review||'')}</textarea></div><div class="info-box blue spacer-top">El cambio de costo se aplica a cálculos nuevos. Las estimaciones guardadas conservan su resultado. El inventario se ajusta por separado con motivo.</div><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Cancelar</button><button class="btn primary" type="submit">Guardar producto</button></div></form>`);}
function c28Adjust(sku){const p=product(sku);showModal(`<h2 id="modal-title">Ajuste de inventario</h2><p class="modal-subtitle">${esc(p.name)} · ${esc(p.sku)}</p><form id="c28-adjust-form" data-sku="${esc(sku)}"><div class="form-grid">${ERP.select('c28-adjust-pool','Tipo de existencia',[{value:'good',label:'Físico vendible'},{value:'quarantine',label:'En inspección'},{value:'damaged',label:'No vendible'},{value:'safety',label:'Stock de seguridad'}],'good')}${ERP.field('c28-adjust-qty','Nueva cantidad',p.good,'number','min="0" step="1" required')}</div><div class="field spacer-top"><label for="c28-adjust-reason">Motivo *</label><textarea id="c28-adjust-reason" rows="3" required></textarea></div><div class="info-box blue spacer-top">Se guardará la diferencia, la existencia total anterior, la nueva cantidad total y el motivo. El ajuste se registra en el almacén principal; para cambiar mercancía de ubicación usa Traspasar.</div><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Cancelar</button><button class="btn primary" type="submit">Registrar ajuste</button></div></form>`);}
function c28Incidents(){const list=issues();return `${pageHead('CONTROL / INCIDENCIAS','Cada pendiente tiene un siguiente paso.','Pagos a proveedores, seguimiento comercial, devoluciones y diferencias de conciliación.',`<button class="btn" data-view="orders">Consultar ventas</button>`)}<div class="mini-metrics">${metric('Pagos a proveedores',list.filter(i=>i.type==='supplier-payment').length,'Cuotas vencidas, hoy o en los próximos 7 días','clock')}${metric('Ventas en seguimiento',list.filter(i=>i.type==='order').length,'Revisa la ficha y registra una resolución','bag')}${metric('Diferencias de liquidación',list.filter(i=>i.type==='settlement').length,'Con estimación y depósito confirmados','wallet')}${metric('Productos por atender',list.filter(i=>i.type==='stock').length,'Existencias bajas o datos por revisar','box')}</div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Asunto</th><th>Referencia</th><th>Tipo</th><th></th></tr></thead><tbody>${list.map(i=>`<tr><td>${esc(i.title)}</td><td>${esc(i.detail)}</td><td>${badge(i.type==='supplier-payment'?'Pago a proveedor':i.type==='stock'?'Inventario':i.type==='settlement'?'Conciliación':'Seguimiento',i.tone||'amber')}</td><td><button class="btn small" ${PaymentAlerts28.issueTarget(i)}>Revisar</button></td></tr>`).join('')||'<tr><td colspan="4" class="empty">No hay incidencias pendientes.</td></tr>'}</tbody></table></div></section>`;}
function c28Audit(){return `${pageHead('CONTROL / BITÁCORA','Los cambios dejan una huella.','Consulta el historial de esta instancia y conserva un respaldo de los registros.',`<button class="btn" data-v28="audit-refresh">Actualizar bitácora</button><button class="btn primary" data-v28="backup">${icon('download')} Descargar respaldo JSON</button>`)}<div class="intro-strip">${icon('shield')}<span>Versión ${ERP.revision} · ${ERP.workspace==='v28'?'Operación V28':'Práctica'} · Guardado ${c28Date(ERP.updatedAt)}. El respaldo conserva identificadores y valores vacíos.</span></div><section class="panel"><div class="panel-head"><h2>Operaciones guardadas en el servidor</h2><span class="tiny">Hasta 500 operaciones recientes</span></div><div id="c28-server-audit" class="panel-body"><p class="small-note">Pulsa Actualizar bitácora para consultar las operaciones confirmadas.</p></div></section><section class="panel spacer-top"><div class="panel-head"><h2>Historial de operación</h2></div><div class="panel-body">${eventList(80)}</div></section><div class="note-panel">La fuente V28 conserva ${state.sourceAudit?.length||0} entradas históricas de cambios en el respaldo. Los cambios nuevos se registran por operación, con fecha y revisión.</div>${ERP.workspace==='practice'?'<button class="btn spacer-top" data-action="reset">Restablecer datos de práctica</button>':''}`;}
function c28Project(){const coverage=[['Pedidos y ventas','Alta con partidas, búsqueda, seguimiento, cancelación, reembolso y resolución.','orders'],['Inventario','Reserva, envío, inspección, reintegro, no vendible, ajustes y recepción de compras.','inventory'],['Productos','Alta y actualización, costo, UPC/SKU/SAT, categorías y excepciones de envío.','products'],['Compras','Documento, partidas de mercancía, recepción, consultas y abonos.','purchases'],['Gastos','Alta, edición, clasificación, consultas, saldos y abonos.','expenses'],['Crédito y calendario','Dadores, instrumentos, corte, vencimiento y parcialidades recalculadas según pagos.','calendar'],['Precios','Calculadora, cotizador, recomendador UPC, comparación y escenarios guardados.','pricing'],['Conciliación V28','Condiciones por venta, estimación por partidas, borradores, selección y guardado por lotes.','settlements'],['Estadísticas','Fecha documental o creación, periodos, rankings y cotejo SICAR.','statistics'],['Configuración','Tarifas, retenciones, MSI, envíos, mapeos, Tienda Nube y catálogos.','configuration'],['Control','Historial de cambios, exportaciones y respaldo JSON.','audit']];return `${pageHead('PROYECTO / V28','La misma AIMERKA. Más operación.','La lógica anterior se conserva y se complementa con los módulos del Excel.',`<button class="btn primary" data-v28="guide">Probar recorrido</button>`)}<div class="intro-strip">${icon('info')}<span>Prototipo funcional con persistencia. La operación con marketplaces, bancos y facturación requiere sus conexiones y validación.</span></div><section class="panel"><div class="panel-head"><h2>Cobertura funcional</h2><span class="tiny">Fuente: ERP_AIMERKA_V28_CONCILIACION_LOTES_PRUEBA.xlsm</span></div><div class="table-wrap"><table><thead><tr><th>Módulo</th><th>Funciones disponibles</th><th></th></tr></thead><tbody>${coverage.map(([name,detail,route])=>`<tr><td><strong>${name}</strong></td><td>${detail}</td><td><button class="btn small" data-view="${route}">Abrir</button></td></tr>`).join('')}</tbody></table></div></section><div class="project-layout spacer-top"><section class="panel project-block"><h2>Qué se conservó</h2><p>Identidad visual, búsqueda por pedido original, separación de reservas y físico, reembolsos sin entradas automáticas, inspección, reintegros, incidencias y calculadora libre.</p><h3>Cómo se incorporó V28</h3><p>Los datos se importaron con sus referencias originales. Las macros se tradujeron a operaciones del servidor y de la interfaz; no se ejecuta VBA. Los botones de navegación y edición de celdas se representan con pantallas, filtros y formularios.</p></section><section class="panel project-block"><h2>Alcance de esta instancia</h2><p>Una empresa y un almacén, con acceso privado. Los cambios se guardan en una base de datos y se detectan guardados simultáneos para evitar sobrescribir otra ventana.</p><p>La conciliación registra el importe total confirmado por venta, tal como V28. Los abonos de compras y gastos sí se acumulan. Las estimaciones reflejan reglas del archivo y requieren contrastarse con los reportes reales.</p><p>Las APIs de VentiApp, SICAR, marketplaces, bancos y facturación aún no están conectadas. Las ventas nuevas se capturan manualmente en este prototipo.</p></section></div>`;}
window.guideV28=function(){showModal(`<h2 id="modal-title">Recorrido de AIMERKA V28</h2><p class="modal-subtitle">La operación anterior, complementada con el Excel.</p><ol class="scope-list"><li><strong>Elige tu espacio.</strong> V28 contiene la copia del archivo; Práctica permite ensayar con ejemplos.</li><li><strong>Registra una venta.</strong> Añade partidas y conserva el pedido original. Abre su ficha para enviar o cancelar.</li><li><strong>Prueba una devolución.</strong> Reembolso, recepción a inspección y reintegro son pasos separados.</li><li><strong>Registra una compra o un gasto.</strong> Agrega mercancía, configura el crédito y registra abonos.</li><li><strong>Concilia un lote.</strong> Selecciona ventas, ajusta condiciones, estima y guarda depósitos preparados.</li><li><strong>Consulta estadísticas.</strong> Cambia fecha base, periodo y canal; revisa los productos más vendidos.</li></ol><div class="modal-actions"><button class="btn" data-action="close-modal">Cerrar</button><button class="btn primary" data-action="guide-start">Registrar venta</button></div>`);};
function c28Integrations(){return `${pageHead('CONEXIONES / INTEGRACIONES','La operación, preparada para conectarse.','El registro manual y la copia V28 ya alimentan el ERP. Las conexiones externas serán la siguiente etapa.',`<button class="btn" data-action="duplicate">${icon('refresh')} Repetir última operación</button>`)}<div class="integration-grid"><section class="panel integration-card integration-main"><div class="integration-brand"><div class="integration-letter">V</div><div><h2>VentiApp</h2><div class="panel-sub">Puente inicial previsto</div></div>${badge('Sin conectar','slate')}</div><p>La conexión se diseñará para recibir pedidos, cambios y referencias de la operación multicanal. Requiere validar los datos y permisos disponibles en la cuenta de HAVANI.</p><div class="integration-steps"><strong>Marketplaces</strong><span>→</span><strong>VentiApp</strong><span>→</span><strong>AIMERKA</strong></div><button class="btn primary small" data-v28="sale-new">${icon('plus')} Registrar venta manual</button></section><section class="panel integration-card"><div class="integration-brand"><div class="integration-letter">S</div><div><h2>SICAR X</h2><div class="panel-sub">Referencias históricas</div></div></div>${badge('Histórico V28 incorporado','green')}<p>Se conservan folios, números originales de pedido, fechas documentales y fechas de creación del archivo. La búsqueda relaciona estas referencias en la ficha de la venta.</p><p class="tiny">La copia inicial no consulta SICAR en tiempo real. Los registros sin partidas verificadas se señalan para revisión.</p><button class="btn small" data-view="statistics">Revisar cotejo SICAR ${icon('arrow')}</button></section>${markets.map(m=>`<section class="panel integration-card"><div class="integration-brand">${MarketUI.logo(m,'lg')}<div><h3>${esc(m)}</h3><span class="panel-sub">Conector por cuenta vendedora</span></div></div>${badge('API pendiente','slate')}<p>Pedidos, cancelaciones, existencias, publicaciones y liquidaciones tendrán una validación propia antes de activar la sincronización.</p><button class="btn small" data-market-info="${esc(m)}">Qué debemos validar ${icon('arrow')}</button></section>`).join('')}</div><section class="panel spacer-top"><div class="panel-head"><div><h2>Control de operaciones repetidas</h2><div class="panel-sub">Repetir la misma operación conserva su resultado y no vuelve a mover existencias ni registrar pagos.</div></div><button class="btn small" data-view="audit">Abrir bitácora</button></div><div class="panel-body"><p class="small-note">El botón superior permite comprobarlo con la última operación realizada en esta ventana. Los cambios se guardan en el servidor.</p>${eventList(12)}</div></section>`;}
renderers.dashboard=c28Dashboard;renderers.orders=c28OrdersPage;renderers.inventory=c28Inventory;renderers.products=c28Products;renderers.incidents=c28Incidents;renderers.audit=c28Audit;renderers.project=c28Project;renderers.integrations=c28Integrations;

document.addEventListener('click',async e=>{
 const el=e.target.closest('button');if(!el)return;
 if(el.dataset.c28OrderAction){c28ActionForm(el.dataset.c28OrderAction,el.dataset.id);return;}
 if(el.dataset.c28ProductEdit){c28ProductForm(el.dataset.c28ProductEdit);return;}
 if(el.dataset.c28Adjust){c28Adjust(el.dataset.c28Adjust);return;}
 if(el.dataset.c28Recommend){closeDrawer();window.Price28?.openProduct(el.dataset.c28Recommend);return;}
 if(el.dataset.c28Recon){closeDrawer();navigate('settlements');window.rec28Open?.(el.dataset.c28Recon);return;}
 if(el.dataset.c28Page){c28.orderPage=Number(el.dataset.c28Page);render();return;}
 if(el.dataset.c28RemoveLine!=null){c28ReadSale();c28.draft.items.splice(Number(el.dataset.c28RemoveLine),1);c28SaleForm();return;}
 if(el.dataset.v28Filter){if(el.dataset.v28Filter==='no-stock'){c28.inventoryMode='empty';navigate('inventory');}else{statusFilter=el.dataset.v28Filter;orderQuery='';navigate('orders');}return;}
 const action=el.dataset.v28;if(!action)return;
 if(action==='sale-new')window.saleFormV28();
 else if(action==='product-new')c28ProductForm();
 else if(action==='sale-add-line'){c28ReadSale();c28.draft.items.push({sku:state.products[0]?.sku,qty:1,unitPriceCents:null});c28SaleForm();}
 else if(action==='guide')window.guideV28();
 else if(action==='backup')ERP.download('AIMERKA-'+ERP.workspace+'-'+ERP.today()+'.json',JSON.stringify({format:'aimerka-v28-backup',workspace:ERP.workspace,revision:ERP.revision,exportedAt:new Date().toISOString(),state},null,2),'application/json');
 else if(action==='orders-export')ERP.downloadCSV('AIMERKA-ventas.csv',[['ID','Pedido original','Marketplace','Folio SICAR','Fecha documento','Fecha creación','Estado comercial','Estado pago','Seguimiento','Total MXN'],...filteredOrders().map(o=>[o.id,o.number,o.market,o.sicar,c28Date(o.documentDate),c28Date(o.creationDate),c28Commercial(o),c28Payment(o),o.followupStatus,D.orderTotal(o)/100])]);
 else if(action==='inventory-export'||action==='products-export')ERP.downloadCSV('AIMERKA-productos.csv',[['SKU','UPC','Nombre','Marca','Categoría','Costo MXN','Precio mercado MXN','Físico vendible','Reservado','Inspección','No vendible','Seguridad','Disponible','Existencia origen','Revisión'],...state.products.map(p=>[p.sku,p.upc,p.name,p.brand,p.category,p.costCents/100,p.priceCents/100,p.good,p.reserved,p.quarantine,p.damaged,p.safety,D.available(p),p.sourceStock,p.review])]);
 else if(action==='audit-refresh'){try{const response=await fetch('/api/audit?workspace='+ERP.workspace),data=await response.json();if(!response.ok)throw new Error(data.error);document.getElementById('c28-server-audit').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Revisión</th><th>Fecha</th><th>Operación</th><th>Resultado</th><th>Operador</th></tr></thead><tbody>${data.rows.map(row=>{let result;try{result=JSON.parse(row.result);}catch{result={message:''};}return `<tr><td>${row.revision}</td><td>${esc(row.created_at)}</td><td>${esc(row.type)}</td><td>${esc(result.message)}</td><td>${esc(row.actor)}</td></tr>`;}).join('')||'<tr><td colspan="5">Sin operaciones nuevas.</td></tr>'}</tbody></table></div>`;}catch(error){toast(error.message,true);}}
});
document.addEventListener('input',e=>{if(e.target.id==='c28-product-query'){const pos=e.target.selectionStart;c28.productQuery=e.target.value;render();const input=document.getElementById('c28-product-query');input.focus();input.setSelectionRange(pos,pos);}});
document.addEventListener('change',e=>{
 if(e.target.id==='c28-sale-warehouseId'){c28ReadSale();c28SaleForm();}
 if(e.target.id==='c28-year'){c28.year=Number(e.target.value);render();}
 if(e.target.id==='c28-inventory-mode'){c28.inventoryMode=e.target.value;render();}
 if(e.target.id==='c28-order-from'){c28.orderFrom=e.target.value;c28.orderPage=1;render();}
 if(e.target.id==='c28-order-to'){c28.orderTo=e.target.value;c28.orderPage=1;render();}
 if(e.target.dataset.c28SaleProduct!=null){const row=e.target.closest('[data-c28-sale-row]'),p=product(e.target.value);row.querySelector('[data-field="price"]').value=(p?.priceCents||0)/100;}
 if(e.target.id==='c28-adjust-pool'){const p=product(document.getElementById('c28-adjust-form').dataset.sku);document.getElementById('c28-adjust-qty').value=p[e.target.value]||0;}
});
document.addEventListener('submit',async e=>{
 const form=e.target;
 if(form.id==='c28-sale-form'){e.preventDefault();const result=await ERP.command('sale.create',c28ReadSale());if(result.ok){form.closest('dialog').close();orderDetails(result.result.orderId||result.result.id);}}
 else if(form.id==='c28-order-action-form'){e.preventDefault();const action=form.dataset.type,payload={orderId:form.dataset.id,reason:c28Value('c28-reason')};if(action==='note'){payload.comments=payload.reason;payload.priority=c28Value('c28-priority');payload.followupStatus=c28Value('c28-followup');}if(action==='refund')payload.amountCents=c28Cash('c28-refund-amount');if(action==='return_receive')payload.confirmPhysical=!!document.getElementById('c28-confirm-physical')?.checked;const result=await ERP.command('sale.'+action,payload);if(result.ok){form.closest('dialog').close();orderDetails(payload.orderId);}}
 else if(form.id==='c28-product-form'){e.preventDefault();const originalSku=form.dataset.original,previous=originalSku?product(originalSku):null,p={...(previous||{}),sku:c28Value('c28-product-sku'),upc:c28Value('c28-product-upc'),name:c28Value('c28-product-name'),brand:c28Value('c28-product-brand'),category:c28Value('c28-product-category'),costCents:c28Cash('c28-product-cost'),averageCostMxn:Number(c28Value('c28-product-cost')),priceCents:c28Cash('c28-product-price'),shippingType:c28Value('c28-product-shipping'),shippingException:c28Value('c28-product-shipping-exception'),satCode:c28Value('c28-product-sat'),department:c28Value('c28-product-department'),safety:Number(c28Value('c28-product-safety')),minStock:Number(c28Value('c28-product-min')),status:c28Value('c28-product-status'),review:c28Value('c28-product-review'),categoryOverrides:{...(previous?.categoryOverrides||{})}};ERP.engines.pricing.CHANNELS.forEach((ch,i)=>p.categoryOverrides[ch]=c28Value('c28-product-override-'+i));const result=await ERP.command('product.save',{originalSku:originalSku||null,product:p});if(result.ok){form.closest('dialog').close();productDetails(p.sku);}}
 else if(form.id==='c28-adjust-form'){e.preventDefault();const result=await ERP.command('inventory.adjust',{sku:form.dataset.sku,pool:c28Value('c28-adjust-pool'),quantity:Number(c28Value('c28-adjust-qty')),reason:c28Value('c28-adjust-reason')});if(result.ok){form.closest('dialog').close();if(!document.getElementById('drawer').hidden)productDetails(form.dataset.sku);}}
});
